{
 "slug": "telemetry-ingestion-processing",
 "tech_stack": {
  "language": "Java 21",
  "framework": "Spring Boot 3 WebFlux",
  "style": "Reactive Event-Driven Stream Processing",
  "build": "Maven (./mvnw)",
  "persistence_access": "Spring Data R2DBC, Flyway migrations, embedded H2 for boot/test only",
  "test": "spring-boot-starter-test, reactor-test"
 },
 "topology": "modular monolith, hexagonal per module; one deployable, one composition root",
 "bounded_contexts": [
  "Telemetry Ingestion & Validation",
  "Telemetry Stream Distribution"
 ],
 "modules": [
  {
   "context": "Telemetry Ingestion & Validation",
   "module": "ingestion",
   "role": "core; owns validation, reordering, append-only raw records and Event Revisions; publishes events"
  },
  {
   "context": "Telemetry Stream Distribution",
   "module": "distribution",
   "role": "derived transient sliding-window buffer; consumes ingestion events by published contract only; broadcasts WindowedTelemetryBroadcast"
  }
 ],
 "layers": [
  "domain (pure; owns invariants)",
  "application (use cases, inbound/outbound ports, no framework)",
  "infrastructure (R2DBC adapters, in-process event bus adapter, config)",
  "interface (WebFlux controllers, event consumers; call application ports only)",
  "composition root (single @SpringBootApplication in base package)"
 ],
 "module_layout": {
  "base_package": "com.pulsestream.telemetry",
  "packages": [
   "com.pulsestream.telemetry.ingestion.domain",
   "com.pulsestream.telemetry.ingestion.application",
   "com.pulsestream.telemetry.ingestion.infrastructure",
   "com.pulsestream.telemetry.ingestion.interfaces",
   "com.pulsestream.telemetry.distribution.domain",
   "com.pulsestream.telemetry.distribution.application",
   "com.pulsestream.telemetry.distribution.infrastructure",
   "com.pulsestream.telemetry.distribution.interfaces",
   "com.pulsestream.telemetry.shared"
  ],
  "integration": {
   "external -> Telemetry Ingestion & Validation": "Conformist; interface-layer anti-corruption mapping of device payload to Telemetry Sample commands; boundary validation + VALIDATION_FAILED tagging + reactive backpressure at the entry point",
   "Telemetry Ingestion & Validation -> Telemetry Stream Distribution": "Customer-supplier; published events TelemetrySampleIngested, TelemetrySampleValidationFailed, TelemetryBackfillRevisionAppended via an outbound EventPublisher port (application, ingestion) and a consumer adapter in distribution; eventual consistency; distribution never reads raw storage",
   "Telemetry Stream Distribution -> external": "Open host service / published language WindowedTelemetryBroadcast; consumer demand signalling keeps broadcast non-blocking"
  }
 },
 "build_order": [
  "T0 scaffold (pom.xml, single composition root, test profile, surefire timeout, Flyway runner)",
  "shared kernel (event contracts: TelemetrySampleIngested, TelemetrySampleValidationFailed, TelemetryBackfillRevisionAppended, WindowedTelemetryBroadcast; correlation key)",
  "ingestion.domain",
  "ingestion.application (ports)",
  "database migrations (expand-only)",
  "ingestion.infrastructure",
  "ingestion.interfaces",
  "distribution.domain",
  "distribution.application",
  "distribution.infrastructure",
  "distribution.interfaces",
  "observability + wiring configuration",
  "integration slice (WebTestClient against embedded substitute)"
 ],
 "surfaces": [
  {
   "name": "Ingress packet ingest HTTP inbound",
   "kind": "http",
   "context": "Telemetry Ingestion & Validation",
   "method": "POST",
   "path": "/telemetry/packets",
   "operations": [
    "ingest Ingress Packet carrying Telemetry Samples",
    "validate, reorder by t_device, append raw record or Event Revision"
   ],
   "traced_from": "context-map: external -> Telemetry Ingestion & Validation (Conformist); actors IoT edge device, Bike computer, Smart wearable"
  },
  {
   "name": "Ingestion events consumer",
   "kind": "consumer",
   "context": "Telemetry Stream Distribution",
   "operations": [
    "consume TelemetrySampleIngested",
    "consume TelemetrySampleValidationFailed",
    "consume TelemetryBackfillRevisionAppended",
    "update sliding-window buffer"
   ],
   "traced_from": "context-map: Telemetry Ingestion & Validation -> Telemetry Stream Distribution (Customer-supplier)"
  },
  {
   "name": "Windowed telemetry stream HTTP outbound feed",
   "kind": "http",
   "context": "Telemetry Stream Distribution",
   "method": "GET",
   "path": "/telemetry/stream/windows",
   "operations": [
    "subscribe to WindowedTelemetryBroadcast as a backpressure-aware server-sent event stream"
   ],
   "traced_from": "context-map: Telemetry Stream Distribution -> external (Open host service); actors Downstream streaming analytics consumers"
  }
 ],
 "contexts_without_inbound": [],
 "rules": [
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Every Telemetry Sample is validated against its Sensor Metric Boundary (HR: 30-240 BPM, Power: 0-2500W, Cadence: 0-220 RPM, Swimming Pace: >45 sec/100m) before downstream propagation"
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Invalid samples are tagged VALIDATION_FAILED and the underlying payload is never dropped"
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Packets delayed up to 60 seconds are ordered by t_device, not t_ingress"
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Ingestion entry point applies reactive backpressure with zero blocking I/O on thread pools"
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Raw time-series records are strictly append-only; corrections and backfills append new Event Revisions"
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Backfill Reorder Window: 60-second window within which delayed out-of-order packets are re-indexed chronologically."
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Device Timestamp (t_device): Device-generated epoch timestamp; the chronological ordering key."
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Ingress Timestamp (t_ingress): Arrival time at the ingestion entry point; never used for ordering."
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "VALIDATION_FAILED: Status flag tagged on samples violating a Sensor Metric Boundary; payload is kept."
  },
  {
   "context": "Telemetry Ingestion & Validation",
   "statement": "Telemetry Sample: Individual 1Hz data point of a sensor metric."
  },
  {
   "context": "Telemetry Stream Distribution",
   "statement": "Broadcast honours downstream backpressure and does not block"
  },
  {
   "context": "Telemetry Stream Distribution",
   "statement": "Only samples already validated by Telemetry Ingestion & Validation are propagated"
  }
 ],
 "assumptions": [
  {
   "id": "A1-delivery-identity",
   "status": "RESOLVED (decided here; replaces the discovery Ambiguity)",
   "decision": "Delivery is treated as at-least-once. Discriminator: natural identity (device id, metric, t_device) PLUS the sample value. Resend classes: (a) same identity and same value = retry, a no-op duplicate (no new row, no event, counted); (b) same identity and a different value = correction, appended as a new Event Revision with the next revision number, raw record untouched, TelemetryBackfillRevisionAppended published; (c) new identity = new raw record.",
   "invariant_owner": "Telemetry Ingestion & Validation (ingestion aggregate, enforced in domain and by a unique key on identity + revision in the store)",
   "excludes": "A client-supplied idempotency key is not used (description names none); value is part of the retry test, not part of the identity, so corrections are never silently reclassified as duplicates."
  },
  {
   "id": "A2-late-beyond-window",
   "status": "RESOLVED (decided here; replaces the discovery Open question)",
   "decision": "A packet later than the 60-second Backfill Reorder Window is never dropped: it is appended as an Event Revision flagged late, ordered by t_device, published as TelemetryBackfillRevisionAppended. Exclusion: rejection is not used because payloads are never dropped.",
   "invariant_owner": "Telemetry Ingestion & Validation"
  },
  {
   "id": "A3-validated-propagation-owner",
   "status": "RESOLVED",
   "decision": "Telemetry Ingestion & Validation owns validation and the validation status; it alone decides VALIDATION_FAILED. Distribution trusts the published status and never revalidates: it broadcasts samples whose status is valid (ingested and revision events) and does not place TelemetrySampleValidationFailed samples in broadcast windows (it only counts them).",
   "invariant_owner": "Telemetry Ingestion & Validation (validation); Telemetry Stream Distribution (filter on published status)"
  },
  {
   "id": "A4-unbounded-metrics",
   "status": "RESOLVED posture, value-less",
   "decision": "Ground contact time, respiration and swim stroke telemetry have no named range, and Swimming Pace has only the lower bound >45 sec/100m (no upper bound). No bound is invented; a metric with no configured boundary is accepted unvalidated (validation disabled) and boundaries are bound to configuration keys."
  },
  {
   "id": "A5-split",
   "status": "Assumption",
   "decision": "Two contexts retained as discovered (ingestion/validation and stream distribution); medium confidence."
  }
 ],
 "risks": [
  "Sliding-window size and its relation to the 60-second reorder window are unspecified: window size is a configuration key with no invented default; reported as an open question to the operator",
  "Value-less boundaries (ground contact time, respiration, swim stroke, swimming pace upper bound) leave those metrics unvalidated",
  "At-least-once delivery assumption (A1) may mismatch real device transport; confidence low",
  "Revisions to windows already broadcast are propagated eventually; consumers may see a window then its revision",
  "Reordering buffer and window buffers must be bounded; unbounded buffers are forbidden, overflow policy must be planned without dropping payloads (backpressure, not drop)",
  "Sink lifecycle: multicast fan-out sinks must use onBackpressureBuffer(capacity, false) so a subscriber disconnect cannot terminate ingestion",
  "Log correlation across event-loop hops needs context-propagation or explicit audit passing",
  "Ingested raw telemetry grows continuously (1Hz per metric per device): retention and partitioning is a capacity risk"
 ],
 "persistence": {
  "owner_context": "Telemetry Ingestion & Validation",
  "drivers": [
   "append-only writes at high 1Hz multi-device throughput",
   "non-blocking access (R2DBC compatible, no blocking I/O)",
   "ordered reads by t_device for a device and metric",
   "Event Revisions need a durable history that is never mutated",
   "Telemetry Stream Distribution owns no durable state"
  ],
  "storage_paradigm": {
   "primary": "relational, append-only tables (simplest paradigm meeting ordering, uniqueness and append-only invariants; rejected: document and log stores for lack of the uniqueness and keyset-ordered range reads; revisit if measured write volume exceeds a single relational engine)",
   "derived": "Windowed buffer in distribution: in-memory transient, rebuilt from published events; staleness bounded by the window; no durable store"
  },
  "data_model": {
   "concepts": [
    {
     "name": "RawTelemetryRecord",
     "key": "(device_id, metric, t_device) natural identity; surrogate record id",
     "attributes": [
      "device_id",
      "metric",
      "t_device",
      "t_ingress",
      "value",
      "validation_status (VALID | VALIDATION_FAILED)",
      "payload"
     ],
     "invariants": [
      "append-only, never updated or deleted",
      "validation_status set once at append",
      "payload never dropped, including VALIDATION_FAILED samples"
     ],
     "sensitivity": "health-related biometric data tied to a device id: classify as personal/sensitive; encrypt at rest and in transit; retention defined by operator (open question)"
    },
    {
     "name": "EventRevision",
     "key": "(device_id, metric, t_device, revision_number); refs the raw record by id",
     "attributes": [
      "revision_number",
      "value",
      "validation_status",
      "reason (correction | backfill | late)",
      "t_ingress"
     ],
     "invariants": [
      "append-only, revision numbers strictly increase per identity",
      "a retry with an identical value appends nothing (A1)",
      "unique key on identity + revision_number gives optimistic concurrency under concurrent writers"
     ],
     "sensitivity": "same as RawTelemetryRecord"
    },
    {
     "name": "SampleValidationStatus",
     "key": "carried on each RawTelemetryRecord and EventRevision (no separate table)",
     "invariants": [
      "VALIDATION_FAILED tagged iff a configured Sensor Metric Boundary is violated"
     ],
     "sensitivity": "non-sensitive"
    },
    {
     "name": "AuditEntry",
     "key": "audit_id",
     "attributes": [
      "actor",
      "action",
      "outcome",
      "timestamp",
      "correlation_id"
     ],
     "invariants": [
      "append-only"
     ],
     "sensitivity": "operational; no payload values, no personal data"
    }
   ],
   "relationships": "EventRevision references RawTelemetryRecord by id; no cross-aggregate transaction; one aggregate per transaction",
   "versioning": "revision_number per identity (optimistic)",
   "denormalization": "none"
  },
  "queries": [
   "append raw record or revision (high frequency, write-only, no read-before-write beyond identity lookup by unique key)",
   "lookup latest revision for an identity to classify retry vs correction (strong consistency)",
   "keyset-ordered read by (device_id, metric, t_device) bounded page size; no offsets, no unbounded scans",
   "audit append"
  ],
  "performance": "Non-blocking writes with backpressure; batching allowed; capacity assumptions unmeasured (open question); shard/partition only on measured volume",
  "migration_plan": "Flyway, ordered, expand-only V<n>__snake_case.sql under src/main/resources/db/migration (spring.flyway.locations: classpath:db/migration); PostgreSQL-compatible DDL portable to plain H2 (no vendor-specific types); JDBC url and R2DBC url from distinct placeholders; embedded H2 only through the test-profile document; rollback by restoring from backup, never destructive down-scripts",
  "backup_recovery": "Operator-owned periodic backup and point-in-time restore of the relational store; append-only data allows verification by revision counts; derived windows rebuilt from new events",
  "open_questions": [
   "Retention period and archival of raw telemetry",
   "Expected devices count and sustained write rate for capacity sizing",
   "Sliding-window size"
  ]
 },
 "observability": {
  "step_logs": {
   "Telemetry Ingestion & Validation": [
    "packet received",
    "sample validated",
    "sample tagged VALIDATION_FAILED",
    "duplicate retry ignored",
    "event revision appended",
    "sample appended",
    "ingestion event published"
   ],
   "Telemetry Stream Distribution": [
    "ingestion event consumed",
    "sample added to window",
    "window broadcast",
    "broadcast demand exhausted"
   ]
  },
  "correlation_key": "requestId",
  "uncounted_failures": {
   "uncredentialed event dropped": "refused at the consumer boundary; audited and logged only, no per-device counter (cardinality bound)",
   "stream subscriber beyond cap": "refused with 503; surfaced by the HTTP status, not a separate meter",
   "window overflow dropped": "counted by telemetry.stream.broadcast outcome=dropped"
  },
  "uncounted_steps": {
   "packet received": "counted via telemetry.ingest.samples at sample append; the receipt boundary itself is only logged",
   "sample validated": "outcome counted by telemetry.ingest.samples (status tag)",
   "ingestion event published": "delivery outcome counted by telemetry.stream.broadcast downstream",
   "ingestion event consumed": "log only, counted by telemetry.stream.window.size",
   "sample added to window": "counted by telemetry.stream.window.size",
   "broadcast demand exhausted": "log only; outcome tag on telemetry.stream.broadcast"
  },
  "audit_trail": {
   "fields": [
    "actor",
    "action",
    "outcome",
    "timestamp",
    "correlationId"
   ],
   "port": "AuditTrail (application port; append-only adapter in infrastructure)",
   "records": [
    "packet ingested",
    "sample validation failed",
    "revision appended",
    "window broadcast started/stopped"
   ]
  },
  "metrics": [
   {
    "name": "telemetry.ingest.samples",
    "type": "counter",
    "tags": [
     "metric",
     "status"
    ]
   },
   {
    "name": "telemetry.ingest.validation_failed",
    "type": "counter",
    "tags": [
     "metric"
    ]
   },
   {
    "name": "telemetry.ingest.duplicates",
    "type": "counter",
    "tags": [
     "metric"
    ]
   },
   {
    "name": "telemetry.ingest.revisions",
    "type": "counter",
    "tags": [
     "reason"
    ]
   },
   {
    "name": "telemetry.ingest.append.latency",
    "type": "timer",
    "tags": [
     "outcome"
    ]
   },
   {
    "name": "telemetry.stream.broadcast",
    "type": "counter",
    "tags": [
     "outcome"
    ]
   },
   {
    "name": "telemetry.stream.window.size",
    "type": "gauge",
    "tags": []
   }
  ],
  "metric_tag_policy": "bounded tags only (metric kind, status, outcome, reason); never device ids",
  "export": {
   "logs": "structured ECS JSON lines to a local append-only rolling file sink (logs/telemetry-ingestion-processing.log); external log collectors read the file, never the app",
   "audit": "append-only audit_trail table plus the same structured fields in the log file",
   "metrics": "Micrometer via actuator; no scrape endpoint unless the description names one",
   "runtime_dependency": "none on external tools; boot test passes with them absent"
  }
 }
}

